<div class="page-head"><div><h1>Users</h1><p class="muted"><?= count($users) ?> of <?= $limit ?> users allowed by your package. Staff permissions can never exceed your own.</p></div><div class="page-actions"><?php if (count($users) < $limit): ?><a class="btn" href="/admin/users/new/"><?= icon('plus', 16) ?> Invite user</a><?php endif ?></div></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Access</th><th>Last sign-in</th><th>Status</th></tr></thead><tbody>
<?php foreach ($users as $u): ?><tr><td><a class="strong" href="/admin/users/<?= (int) $u['id'] ?>/"><?= e($u['name'] ?: '—') ?></a></td><td><?= e($u['email']) ?></td><td><?= e(ucwords(str_replace('_', ' ', $u['role']))) ?></td><td class="small"><?= $u['role'] === 'owner' ? 'Everything' : e(implode(', ', array_map(static fn($p) => shop_permissions()[$p] ?? $p, $u['perms']))) ?></td><td class="small"><?= e(fmt_date($u['last_login_at'], true)) ?></td><td><?= $u['status'] === 'active' ? ($u['password_hash'] ? '<span class="badge badge-ok">Active</span>' : '<span class="badge badge-warn">Invited</span>') : '<span class="badge badge-muted">Disabled</span>' ?></td></tr><?php endforeach ?>
</tbody></table></div>
